CREATE OR REPLACE FUNCTION public.create_association_with_owner(target_id text, target_name text, target_short_name text DEFAULT ''::text, target_timezone text DEFAULT 'America/Toronto'::text, target_logo_data_url text DEFAULT NULL::text, target_website_url text DEFAULT NULL::text, target_sponsor_logos jsonb DEFAULT '[]'::jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_org_id uuid;
  v_profile_id uuid;
  v_slug text;
  v_result json;
begin
  v_org_id := coalesce(nullif(target_id, '')::uuid, gen_random_uuid());
  v_slug := lower(regexp_replace(coalesce(target_name, ''), '[^a-zA-Z0-9]+', '-', 'g'))
            || '-' || substring(v_org_id::text, 1, 8);

  insert into public.organizations (id, name, short_name, timezone, logo_url, website_url, sponsor_logos, slug)
  values (v_org_id, target_name, coalesce(target_short_name,''), coalesce(target_timezone,'America/Toronto'),
          target_logo_data_url, target_website_url, coalesce(target_sponsor_logos,'[]'::jsonb), v_slug)
  on conflict (id) do update set
    name        = excluded.name,
    short_name  = excluded.short_name,
    timezone    = excluded.timezone,
    logo_url    = excluded.logo_url,
    website_url = excluded.website_url,
    updated_at  = now();

  -- Link calling user as admin member
  select id into v_profile_id from public.user_profiles where user_id = auth.uid();
  if v_profile_id is not null then
    insert into public.organization_members (user_id, organization_id, role)
    values (v_profile_id, v_org_id, 'admin')
    on conflict (organization_id, user_id) do nothing;
  end if;

  select row_to_json(o) into v_result
  from (
    select id, name, short_name, timezone, logo_url as logo_data_url, website_url, sponsor_logos, created_at, updated_at
    from public.organizations where id = v_org_id
  ) o;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_class_refs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  block_record record;
  directory_organization_id uuid;
  template_record record;
begin
  select organization_id, show_id into block_record
  from public.blocks
  where id = new.block_id;

  if not found then
    raise exception 'Block % does not exist', new.block_id
      using errcode = 'foreign_key_violation';
  end if;

  select organization_id into directory_organization_id
  from public.organization_disciplines
  where id = new.organization_discipline_id
    and is_active;

  if directory_organization_id is null
    or directory_organization_id is distinct from block_record.organization_id then
    raise exception 'Class discipline directory must be active and belong to the block organization'
      using errcode = 'check_violation';
  end if;

  if new.class_template_id is not null then
    select organization_id, organization_discipline_id into template_record
    from public.class_templates
    where id = new.class_template_id;

    if not found
      or template_record.organization_id is distinct from block_record.organization_id
      or template_record.organization_discipline_id is distinct from new.organization_discipline_id then
      raise exception 'Class template must belong to the same organization and discipline directory'
        using errcode = 'check_violation';
    end if;
  end if;

  if new.organization_id is not null
    and new.organization_id is distinct from block_record.organization_id then
    raise exception 'Class organization must match its block organization'
      using errcode = 'check_violation';
  end if;

  if new.show_id is not null
    and new.show_id is distinct from block_record.show_id then
    raise exception 'Class show must match its block show'
      using errcode = 'check_violation';
  end if;

  new.organization_id := block_record.organization_id;
  new.show_id := block_record.show_id;
  return new;
end;
$function$

