CREATE OR REPLACE FUNCTION public.set_class_template_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  parent_organization_id uuid;
  directory_organization_id uuid;
